mutation.search:
outputText(value) {
    this.checkOutput(value.length);
    const size = Buffer.byteLength(value);
    this.checkOutput(size);
    return size;
}

mutation.replacement:
outputText(value) {
    this.checkOutput(value.length);
    const size = value.length;
    this.checkOutput(size);
    return size;
}
